import { decodeXmlEntities, efetchUrl, eutilsText } from './eutils'
import { isAbortError } from './fetch'
import { bestEffort, createDbOpener } from './idb'

import type { DBSchema } from 'idb'

const DB_NAME = 'jbrowse-msaview-taxonomy-cache'
const STORE_NAME = 'common-names'
const DB_VERSION = 2

interface CachedTaxonomy {
  taxid: number
  sciname: string
  commonName?: string
}

interface TaxonomyCacheDB extends DBSchema {
  [STORE_NAME]: {
    key: number
    value: CachedTaxonomy
  }
}

const getDB = createDbOpener<TaxonomyCacheDB>(DB_NAME, DB_VERSION, db => {
  if (db.objectStoreNames.contains(STORE_NAME)) {
    db.deleteObjectStore(STORE_NAME)
  }
  db.createObjectStore(STORE_NAME, { keyPath: 'taxid' })
})

function getCachedTaxonomies(taxids: number[]) {
  return bestEffort(
    'taxonomy cache read',
    async () => {
      const db = await getDB()
      const tx = db.transaction(STORE_NAME, 'readonly')
      const results = await Promise.all(
        taxids.map(taxid => tx.store.get(taxid)),
      )
      await tx.done
      return results
    },
    [],
  )
}

function saveTaxonomyCache(entries: CachedTaxonomy[]) {
  return bestEffort(
    'taxonomy cache write',
    async () => {
      const db = await getDB()
      const tx = db.transaction(STORE_NAME, 'readwrite')
      for (const entry of entries) {
        await tx.store.put(entry)
      }
      await tx.done
    },
    undefined,
  )
}

export interface TaxonomyInfo {
  sciname: string
  commonName?: string
}

export async function fetchTaxonomyInfo(
  taxidsWithRepeats: number[],
  signal?: AbortSignal,
): Promise<Map<number, TaxonomyInfo>> {
  // callers pass one taxid per alignment row, and a BLAST hit list is several
  // rows per species: 100 albumin hits are maybe 50 taxa, and asking as they
  // came did 100 IndexedDB reads and sent eutils 100 ids for 50 answers. The
  // result is keyed by taxid, so no caller can tell the difference
  const taxids = [...new Set(taxidsWithRepeats)]
  const result = new Map<number, TaxonomyInfo>()
  const uncachedTaxids: number[] = []
  const cachedResults = await getCachedTaxonomies(taxids)

  for (let i = 0; i < taxids.length; i++) {
    const taxid = taxids[i]!
    const cached = cachedResults[i]
    if (cached) {
      result.set(taxid, {
        sciname: cached.sciname,
        commonName: cached.commonName,
      })
    } else {
      uncachedTaxids.push(taxid)
    }
  }

  if (uncachedTaxids.length === 0) {
    return result
  }

  const batchSize = 100
  const toCache: CachedTaxonomy[] = []

  for (let i = 0; i < uncachedTaxids.length; i += batchSize) {
    const batch = uncachedTaxids.slice(i, i + batchSize)
    const idsParam = batch.join(',')

    try {
      // textfetch rather than a bare fetch: an NCBI 429/5xx returns an HTML
      // error body that the regexes below silently find nothing in, so without
      // the status check a throttled batch looks like "these taxa have no
      // names" instead of reporting why
      const text = await eutilsText(
        efetchUrl({ db: 'taxonomy', id: idsParam, retmode: 'xml' }),
        { signal },
      )

      // Build a map of taxid -> taxon block by finding Taxon elements.
      // Prefer entries with <LineageEx> (full top-level entries) over nested
      // entries inside another taxon's LineageEx
      const taxonMap = new Map<number, string>()
      const taxonRegex = /<Taxon>\s*<TaxId>(\d+)<\/TaxId>/g
      let match
      while ((match = taxonRegex.exec(text)) !== null) {
        const matchedTaxid = Number(match[1])
        const startIdx = match.index

        // Find the matching closing </Taxon> by counting nesting depth
        let depth = 1
        let endIdx = startIdx + match[0].length
        while (depth > 0 && endIdx < text.length) {
          const openMatch = text.indexOf('<Taxon>', endIdx)
          const closeMatch = text.indexOf('</Taxon>', endIdx)
          if (closeMatch === -1) {
            break
          }
          if (openMatch !== -1 && openMatch < closeMatch) {
            depth++
            endIdx = openMatch + 7
          } else {
            depth--
            endIdx = closeMatch + 8
          }
        }

        const taxonXml = text.slice(startIdx, endIdx)
        const existing = taxonMap.get(matchedTaxid)
        const hasLineageEx = taxonXml.includes('<LineageEx>')
        const existingHasLineageEx = existing?.includes('<LineageEx>')
        if (!existing || (hasLineageEx && !existingHasLineageEx)) {
          taxonMap.set(matchedTaxid, taxonXml)
        }
      }

      for (const taxid of batch) {
        const taxonXml = taxonMap.get(taxid)
        if (taxonXml) {
          const genbankCommon =
            /<GenbankCommonName>(.*?)<\/GenbankCommonName>/.exec(taxonXml)
          const commonName = /<CommonName>(.*?)<\/CommonName>/.exec(taxonXml)
          const sciName = /<ScientificName>(.*?)<\/ScientificName>/.exec(
            taxonXml,
          )
          const rawName = genbankCommon?.[1] ?? commonName?.[1]
          const name = rawName && decodeXmlEntities(rawName)

          const sci = decodeXmlEntities(sciName?.[1] ?? '')
          result.set(taxid, { sciname: sci, commonName: name })
          toCache.push({ taxid, sciname: sci, commonName: name })
        }
      }
    } catch (error) {
      if (isAbortError(error)) {
        await saveTaxonomyCache(toCache)
        throw error
      }
      console.error('Failed to fetch taxonomy data:', error)
    }
  }

  if (toCache.length > 0) {
    await saveTaxonomyCache(toCache)
  }

  return result
}
